PF_CPP='\n#include <cstdint>\n#include <vector>\nvoid vq8_forward(int64_t,int64_t,int64_t,int64_t,int64_t,int64_t,int64_t,int64_t,int64_t,int64_t,int64_t,int64_t,int64_t,int64_t,\n int64_t,int64_t,int64_t,int64_t,int64_t,int64_t,int64_t,int64_t,int64_t,double,int64_t,int64_t,int64_t);\nstd::vector<int64_t> vq8_resources(int64_t);\n'
# Embedded into the lab payload. Only setup is shortened; every timed S11
# function and every selected expert/attention/projection gate is unchanged.
def tl_prepare_selected(host, weights):
    from concurrent.futures import ThreadPoolExecutor
    started=time.monotonic()
    host._BEST5_DEADLINE=started+235.
    device=weights['qkv_gate'].device
    builds=[host._layer_attn_ext,host._vq8_module,host._v9_recoded_module,
            host.nf_module,host.smallm_module,host._glue_cl_ext]
    if host._attn_port_hopper(device):builds.append(host._attn_port_ext)
    if host._fa3_on_device(device):builds.append(host._lt_module)
    with ThreadPoolExecutor(max_workers=8) as pool:
        futures=[pool.submit(fn) for fn in builds]
        state=host._prepare_weights(weights)
        for future in futures:future.result()
    host._seed_v9_gemv_choices(state)
    flush=torch.empty(256<<20,device=device,dtype=torch.uint8)
    # Keep the original pinned projection constructors, Lt heuristic tables,
    # lossless layouts and their FP32/replay guards. No projection is substituted.
    state['proj_plan']=host._tune_projections(state,flush,device)
    host._tune_measured_lt(state,flush,device)
    state.pop('_proj_data',None);state.pop('_proj_stream',None)
    # All twelve BEST7_SETTINGS attention/expert choices are explicit. The
    # portfolio tuner and its unselected adapters cannot influence these calls.
    assert all(row[1]!='auto' and row[2]!='auto' for key,row in host.BEST7_SETTINGS.items() if key!='other')
    state['attention_plan']={(b,l,w):('layer',None) for b in (1,16,32) for l in (1,8) for w in (True,False)}
    state['vq8_rows']=host._vq8_prepare(device)
    assert state['vq8_rows']==host._VQ8_ROWS, 'S11 selected vq8 rows must pass their original gates'
    state['pdl_plan']={(t,p):True for t in host._TUNE_TOKENS for p in ('b1','b2')}
    state['prefix_plan']={t:('regular',True) for t in host._TUNE_TOKENS}
    state['moe_bank_raw']=state['moe_bank']
    state['moe_recoded_mod']=host._v9_recoded_module()
    state['moe_bank']=host._prepare_recoded_bank(weights,state['moe_bank_raw'],state['moe_recoded_mod'])
    state['nf_streams']=(torch.cuda.Stream(device=device),torch.cuda.Event(),torch.cuda.Event())
    host._s4_prepare_banks(state,weights)
    host._gate_split_prepare(state,device)
    # These are S11's original, strict, selected three-stream expert and
    # attention gates, including graph replays. They still raise on failure.
    host._best7_prepare_settings(state,weights,device)
    if torch.cuda.get_device_capability()==(9,0):
        for key,pin in host.PROJ_PINS.items():
            assert state['proj_plan'][key]==pin, ('pinned projection rejected',key,state['proj_plan'][key],pin)
    torch.cuda.synchronize()
    print('TL_SELECTED_PREPARE seconds=%.3f selected_gates=%d pins=%s'%
          (time.monotonic()-started,len(state['best7_gates']),repr(state['proj_plan'])),flush=True)
    return state

# This file is embedded with frozen S11 and activity.cpp by build.py.
TL_CASES = tuple((b, q, w) for q in (1, 8) for b in (1, 16, 32) for w in (2048, 0))
TL_REPS = 5
TL_RESULTS = []


def tl_activity():
    tag = hashlib.sha256(TL_ACTIVITY.encode()).hexdigest()[:12]
    return load_inline(name='muse_layer_timeline_' + tag, cpp_sources=TL_ACTIVITY,
        functions=['profile_begin', 'profile_end', 'capture_nodes', 'exec_id'],
        no_implicit_headers=True, with_pytorch_error_handling=False,
        extra_include_paths=['/usr/local/cuda/include'],
        extra_ldflags=['-L/usr/local/cuda/lib64', '-Wl,-rpath,/usr/local/cuda/lib64', '-lcupti', '-lcudart'],
        verbose=False)


def tl_host(weights):
    if 'TL_EXISTING_HOST' in globals():
        return TL_EXISTING_HOST
    name = '<timeline_frozen_s11_acda6c62>'
    linecache.cache[name] = (len(TL_S11), None, TL_S11.splitlines(True), name)
    module = types.ModuleType('timeline_s11')
    exec(compile(TL_S11, name, 'exec'), module.__dict__)
    if torch.cuda.get_device_capability() != (9, 0):
        module._ap_fa3_scheduler_metadata = lambda *a, **kw: None
    if 'TL_LOCAL_INSTALL' in globals():
        TL_LOCAL_INSTALL(module)
    state = tl_prepare_selected(module, weights)
    return module, state


def tl_nbytes(value):
    if isinstance(value, torch.Tensor):
        return value.numel() * value.element_size()
    if isinstance(value, (tuple, list)):
        return sum(tl_nbytes(x) for x in value)
    return 0


def tl_capture(host, state, data, act, mapped):
    ns = host.__dict__
    known, stages, outputs = set(), {}, {}
    replacements = {}
    def snapshot():
        return set(act.capture_nodes(torch.cuda.current_stream().cuda_stream))
    def wrap(name, label):
        original = ns[name]
        replacements[name] = original
        def call(*args, **kw):
            if not torch.cuda.is_current_stream_capturing():
                return original(*args, **kw)
            before = snapshot()
            value = original(*args, **kw)
            after = snapshot()
            stage = label(args, kw)
            ids = after - before
            assert not (known & ids), ('nested stage capture', stage)
            known.update(ids)
            for node in ids:
                stages[node] = stage
            outputs[stage] = (args, value)
            return value
        ns[name] = call
    if mapped:
        wrap('_best7_project', lambda a, k: a[1])
        wrap('_best7_attention', lambda a, k: 'attn')
        wrap('_gate_split_apply', lambda a, k: 'gate')
        wrap('_best7_boundary', lambda a, k: a[4])
        wrap('_best7_route', lambda a, k: 'route')
        wrap('_best7_expert', lambda a, k: 'moe')
    try:
        graph = torch.cuda.CUDAGraph()
        with torch.cuda.graph(graph):
            out = host.kernel_fn(data, state)
    finally:
        ns.update(replacements)
    # CUDA 13 CUPTI encodes graph identity in the upper 32 bits and node
    # identity in the lower 32. Instantiation changes the graph id. This is
    # the same rekeying torch.cuda._graph_annotations._rekey_annotations uses.
    if stages:
        eid=act.exec_id(graph.raw_cuda_graph_exec())
        assert len({node >> 32 for node in stages}) == 1
        stages={(eid << 32) | (node & 0xffffffff):stage for node,stage in stages.items()}
    return graph, out, stages, outputs


def tl_times(graph, reps):
    samples = []
    for _ in range(reps):
        a, b = torch.cuda.Event(enable_timing=True), torch.cuda.Event(enable_timing=True)
        lab_cold_l2()
        a.record(); graph.replay(); b.record(); b.synchronize()
        samples.append(a.elapsed_time(b) * 1000)
    return samples


def tl_union(intervals):
    intervals = sorted(intervals)
    merged = []
    for a, b in intervals:
        if merged and a <= merged[-1][1]:
            merged[-1][1] = max(merged[-1][1], b)
        else:
            merged.append([a, b])
    return sum(b - a for a, b in merged)


def tl_footprints(data, state, outputs, host):
    """Compulsory unique logical input reads, not a hardware HBM traffic counter.

    Weights/activations counted once per consuming stage; reuse within the stage
    may add L2 reads. Intermediate reduction traffic is separately attributed.
    """
    cfg = data['config']; m = cfg['tokens']; b = cfg['batch']; q = cfg['q_len']
    result = {}
    for stage, (args, value) in outputs.items():
        if stage in ('qkv_gate', 'qkv3', 'o', 'pool_router', 'unpooler', 'unpooler_slice'):
            result[stage] = dict(read=tl_nbytes(state[stage]) + tl_nbytes(args[0]),
                                 weights=tl_nbytes(state[stage]), input=tl_nbytes(args[0]),
                                 output=tl_nbytes(value[0]), splits=value[1])
        elif stage == 'gate':
            result[stage] = dict(read=tl_nbytes(state['gate_rows']) + tl_nbytes(args[0]) + tl_nbytes(args[1]),
                                 weights=tl_nbytes(state['gate_rows']), output=tl_nbytes(value))
        elif stage == 'attn':
            seq = data['seq_lens'].cpu().tolist()
            # Union of the causal keys read by the q queries in each request.
            keys = sum(min(s + q, cfg['window'] + q - 1) if cfg['window'] else s + q for s in seq)
            kv = keys * cfg['num_kv_heads'] * cfg['head_dim'] * 2
            qkv = tl_nbytes(args[0][0])
            result[stage] = dict(read=kv + qkv + keys * 4 + tl_nbytes(data['seq_lens']) + 8,
                                 kv=kv, keys=keys, qkv=qkv, output=tl_nbytes(value))
        elif stage in ('b1', 'b2'):
            post = stage == 'b2'
            # branch, stream, pre norm weights, alpha, beta, optional post norm
            result[stage] = dict(read=tl_nbytes(args[0][0]) + tl_nbytes(args[1]) + 8192 * 4 * (4 if post else 3),
                                 output=tl_nbytes(value))
        elif stage == 'route':
            result[stage] = dict(read=tl_nbytes(args[0][0]) + tl_nbytes(state['router_bias']) +
                                 tl_nbytes(state['pre_expert_w']) + 4, output=tl_nbytes(value))
        elif stage == 'moe':
            lids = args[3].cpu().flatten().tolist()
            counts = [lids.count(e) for e in range(32)]
            bank = state['moe_bank']
            w13 = tl_nbytes(bank['w13p']) // 32
            w2 = tl_nbytes(bank['w2p']) // 32
            count = sum(c > 0 for c in counts)
            heavy = sum(c > 16 for c in counts)
            light = count - heavy
            tokens = sum(counts)
            result[stage] = dict(read=count * (w13 + w2) + tl_nbytes(args[1]) +
                                 tl_nbytes(args[2]) + tl_nbytes(args[3]) + 8192,
                                 w13=w13, w2=w2, experts=count, heavy=heavy, light=light,
                                 routed=tokens, tokens=m, counts=counts, output=tl_nbytes(value),
                                 repeated_weight_upper=sum(math.ceil(c / 8) for c in counts) * (w13+w2))
    return result


def tl_node_bytes(name, stage, info, ordinal, count):
    """Return logical read lower bound and attribution class per original node.

    Unknown multi-node paths stay explicit (class 'unresolved'), rather than
    distributing bytes in proportion to measured time (circular bandwidth).
    """
    if not info:
        return 0, 'init'
    if count == 1:
        return info['read'], 'stage_unique'
    if stage == 'attn':
        if any(s in name for s in ('attn_main', 'vq8_main', 'flash_fwd', 'Flash', 'flash::', '_attn_split_kernel')):
            return info['kv'] + info['keys'] * 4 + info['qkv'], 'kv_unique'
        if any(s in name for s in ('sumcast', 'qk_prep', 'qk_norm', 'prepare', 'qkv')):
            return info['qkv'], 'qkv_input'
        if 'combine' in name or 'split' in name:
            # Distinct split partials require exact runtime layout, unavailable
            # for FA3; expose unknown rather than invent HBM traffic.
            return info['output'] * 2, 'partial_read_lower_bound'
        if 'gate' in name or 'norm' in name:
            return info['output'], 'attn_output'
        return 0, 'unresolved'
    if stage == 'moe':
        # CUPTI names are demangled in activity.cpp.
        if 'moe_var' in name or 'moe_fused' in name:
            return info['read'], 'expert_unique'
        if 'phase<' in name and name.split('phase<')[1].split(',')[1].strip() == 'true':
            return info['light'] * info['w13'], 'light_w13_unique'
        if 'phase<' in name and name.split('phase<')[1].split(',')[1].strip() == 'false':
            return info['light'] * info['w2'], 'light_w2_unique'
        if 'mwbr::gemm<' in name:
            if name.split('mwbr::gemm<')[1].split(',')[1].strip() == 'true':
                return info['heavy'] * info['w13'], 'heavy_w13_unique'
            if name.split('mwbr::gemm<')[1].split(',')[1].strip() == 'false':
                return info['heavy'] * info['w2'], 'heavy_w2_unique'
        if 'route' in name:
            return info['tokens'] * 8 * 4, 'route_ids'
        if 'finish' in name:
            return info['routed'] * 4096 * 4, 'expert_output'
        return 0, 'unresolved'
    if 'reduce' in name.lower() or 'sum' in name.lower() or 'cast' in name.lower():
        return info.get('output', 0), 'partial_input_lower_bound'
    if 'gemv' in name or 'gemm' in name.lower() or 'cublas' in name:
        return info['read'], 'dense_unique'
    return 0, 'unresolved'


def tl_summarize(records, mapping, footprints):
    rows = [(name, r) for name, r in records if r[4] in mapping]
    if not rows:
        raise RuntimeError('CUPTI returned no mapped graph nodes')
    by_node = {}
    for name, r in rows:
        by_node.setdefault(r[4], []).append((name, r))
    assert all(len(v) == TL_REPS for v in by_node.values()), {k: len(v) for k, v in by_node.items()}
    assert set(by_node) == set(mapping), ('missing graph activity', set(mapping)-set(by_node))
    for v in by_node.values():
        v.sort(key=lambda nr: nr[1][0])
    traces = [[by_node[node][i] for node in by_node] for i in range(TL_REPS)]
    spans = [max(r[1] for _, r in trace) - min(r[0] for _, r in trace) for trace in traces]
    chosen = sorted(range(TL_REPS), key=lambda i: spans[i])[TL_REPS // 2]
    trace = sorted(traces[chosen], key=lambda nr: (nr[1][0], nr[1][1]))
    start = min(r[0] for _, r in trace)
    names = []
    stages = []
    nodes = []
    counters = {}
    count_stage = {s: sum(mapping[r[4]] == s for _, r in trace) for s in set(mapping.values())}
    for i, (name, r) in enumerate(trace):
        stage = mapping[r[4]]
        ordinal = counters.get(stage, 0); counters[stage] = ordinal + 1
        rd, kind = tl_node_bytes(name, stage, footprints.get(stage), ordinal, count_stage[stage])
        a, b = (r[0]-start)/1000, (r[1]-start)/1000
        gap = (trace[i+1][1][0]-r[1])/1000 if i+1 < len(trace) else None
        # Original graph id is preserved, not an eager profiler approximation.
        nodes.append(dict(name=name, stage=stage, node=r[4], stream=r[13], start=a, end=b,
                          next_gap=gap, read=rd, byte_kind=kind,
                          bw=rd/(b-a)/1e6 if b>a else 0,
                          duration_mad=statistics.median(abs((v[1][1]-v[1][0])/1000-(b-a)) for v in by_node[r[4]])))
    wall = spans[chosen]/1000
    union = tl_union((n['start'], n['end']) for n in nodes)
    # Average-rate proxy: piecewise sum of each active node's logical B/duration.
    cuts = sorted({t for n in nodes for t in (n['start'], n['end'])})
    low = sum(b-a for a,b in zip(cuts,cuts[1:]) if sum(n['bw'] for n in nodes
              if n['start'] <= a and n['end'] >= b) < 2.29)
    stage_rows = {}
    for s in count_stage:
        ns = [n for n in nodes if n['stage'] == s]
        lo = min(n['start'] for n in ns); hi = max(n['end'] for n in ns)
        rd = footprints.get(s, {}).get('read', 0)
        stage_rows[s] = dict(start=lo, end=hi, span=hi-lo, read=rd,
                            bw=rd/(hi-lo)/1e6 if hi>lo else 0,
                            residual=max(0, hi-lo-rd/4.58e6))
    deps = {}
    for before, after, label in [('qkv3' if 'qkv3' in stage_rows else 'qkv_gate', 'attn', 'qkv_attn'),
                                  ('pool_router', 'route', 'router_route')]:
        if before in stage_rows and after in stage_rows:
            deps[label] = stage_rows[after]['start']-stage_rows[before]['end']
    rd = sum(f['read'] for f in footprints.values())
    return dict(wall=wall, busy_union=union, kernel_sum=sum(n['end']-n['start'] for n in nodes),
                bubble=wall-union, overlap=sum(n['end']-n['start'] for n in nodes)-union,
                low50_proxy=low, bytes=rd, stream_floor=rd/4.58e6,
                dependencies=deps, stages=stage_rows, nodes=nodes,
                span_samples=[round(x/1000,3) for x in spans], footprints=footprints)


def tl_pack(results):
    # Compact columnar archive keeps every node in the judge's 9KB lab log.
    names, kinds, stages = [], [], []
    def intern(bank, value):
        if value not in bank: bank.append(value)
        return bank.index(value)
    packed = []
    for result in results:
        row = {k:v for k,v in result.items() if k not in ('nodes', 'footprints', 'stages', 'paired_samples')}
        row['nodes'] = [[intern(names,n['name'].replace('(anonymous namespace)','anon').split('(')[0]), intern(stages,n['stage']), n['node'], n['stream'],
                         round(n['start'],3),round(n['end'],3), n['read'],intern(kinds,n['byte_kind']),
                         round(n['duration_mad'],3)] for n in result['nodes']]
        row['paired_ratios']=[round(a/c,5) for a,c in result['paired_samples']]
        row['footprints'] = {s:{k:v for k,v in f.items() if k in
            ('read','experts','heavy','light','counts','kv','keys')} for s,f in result['footprints'].items()}
        packed.append(row)
    archive = dict(version=1, names=names, stages=stages, byte_kinds=kinds,
                   columns=['name','stage','node','stream','start_us','end_us','logical_read_B','byte_kind','duration_mad_us'],
                   results=packed)
    def rounded(x):
        if isinstance(x,float):return round(x,4)
        if isinstance(x,dict):return {k:rounded(v) for k,v in x.items()}
        if isinstance(x,list):return [rounded(v) for v in x]
        return x
    body = json.dumps(rounded(archive),separators=(',',':'))
    blob = base64.b85encode(lzma.compress(body.encode(),preset=6)).decode()
    return blob



def cs_copy(dst,src):
    if isinstance(dst,torch.Tensor):
        assert dst.shape==src.shape
        dst.copy_(src)
    elif isinstance(dst,dict):
        for k in dst:cs_copy(dst[k],src[k])
    elif isinstance(dst,(tuple,list)):
        for a,b in zip(dst,src):cs_copy(a,b)

def cs_delta(got,want):
    return [float((a!=b).any()) if not a.is_floating_point() else float((a.float()-b.float()).norm()/b.float().norm().clamp_min(1e-12)) for a,b in zip(got,want)]

def cs_profile(host,st,data,act):
    act.profile_begin()
    try:
        graph,out,mapping,outputs=tl_capture(host,st,data,act,True)
        lab_cold_l2();graph.replay();torch.cuda.synchronize()
    finally:act.profile_end()
    act.profile_begin()
    try:tl_times(graph,TL_REPS)
    finally:records=act.profile_end()
    footprints=tl_footprints(data,st,outputs,host)
    for node in {r[4] for _,r in records if r[4]}-set(mapping):mapping[node]='init'
    result=tl_summarize(records,mapping,footprints)
    front=0.;increments={}
    for s in ('qkv3','qkv_gate','attn','gate','o','b1','pool_router','route','moe','unpooler_slice','unpooler','b2'):
        if s in result['stages']:
            e=result['stages'][s]['end'];increments[s]=max(0.,e-front);front=max(front,e)
    return graph,out,dict(inc=increments,wall=result['wall'],stages=result['stages'],nodes=[n for n in result['nodes'] if n['stage']=='attn'])


def clock_summary(rows, G):
    """One line from vq8_attention(clocks=...) rows: times in us from the first CTA's entry, wait shares."""
    rows = rows.cpu()
    main, comb = rows[:G], rows[G:]
    comb = comb[comb[:, 0] != 0]
    fused = ''
    if len(comb) == 0:  # fused merge: rows 25 barrier release, 27 slice loaded, 28 slices merged, 26 end (thread 0)
        mrg = main[main[:, 26] != 0]
        comb = torch.stack([mrg[:, 25], mrg[:, 25], mrg[:, 26]], 1)
        live = mrg[mrg[:, 27] != 0]
        d = lambda c: float(((live[:, c] & ((1 << 62) - 1)) - live[:, 25]).double().median()) / 1000.0  # noqa: E731
        fused = ' merge_us slice=%.2f red=%.2f end=%.2f' % (d(27), d(28), d(26)) if len(live) else ''
    act = main[main[:, 10] != -1]
    t0 = int(main[:, 0].min())
    us = lambda x: (x.double() - t0) / 1000.0  # noqa: E731
    med = lambda x: float(x.double().median())  # noqa: E731
    cyc_c, cyc_p = act[:, 5].double().clamp(min=1), act[:, 9].double().clamp(min=1)
    return ("ctas=%d tiles=%d-%d entry_max=%.2f sched=%.2f first=%.2f/%.2f wg0_end=%.2f/%.2f wg1_end_max=%.2f "
            "prod_end_max=%.2f cwait=%.2f/%.2f pempty=%.2f pcp=%.2f comb_entry=%.2f comb_go=%.2f comb_end=%.2f "
            "cyc_per_tile=%.0f cons_go=%.2f bar1=%.2f bar2=%.2f loads=%.2f q_ready=%.2f "
            "per-tile cyc qkw=%.0f smx=%.0f pvw=%.0f iss=%.0f pub=%.0f pis=%.0f" % (
                len(act), int(act[:, 10].min()), int(act[:, 10].max()), float(us(main[:, 0]).max()),
                med(us(act[:, 1]) - us(act[:, 0])), med(us(act[:, 2])), float(us(act[:, 2]).max()),
                med(us(act[:, 3])), float(us(act[:, 3]).max()), float(us(act[:, 13]).max()), float(us(act[:, 6]).max()),
                med(act[:, 4] / cyc_c), med(act[:, 11] / cyc_c), med(act[:, 7] / cyc_p), med(act[:, 8] / cyc_p),
                float(us(comb[:, 0]).min()), float(us(comb[:, 1]).min()), float(us(comb[:, 2]).max()),
                med(cyc_c / act[:, 10].double().clamp(min=1)), med(us(act[:, 14])), med(us(act[:, 16])), med(us(act[:, 17])),
                med(us(act[:, 18])), med(us(act[:, 15])),
                *[med(act[:, c].double() / act[:, 10].double().clamp(min=1)) for c in range(19, 25)])) + fused



PF_MOD={}
PF_CASES=(16,32)
PF_SEEDS=tuple(172903+7919*i for i in range(8))
PF_ROUNDS=8
PF_RESULTS=[]
PF_CLOCKS=True

def pf_module(d,clk=False):
    key=d,clk
    if key not in PF_MOD:
        major,minor=torch.cuda.get_device_capability();arch='90a' if major==9 else f'{major}{minor}'
        tag=hashlib.sha256(PF_CUDA[d].encode()).hexdigest()[:12]
        PF_MOD[key]=load_inline(name=f'vq8_probpoly{d}_{tag}_{arch}_{int(clk)}',cpp_sources=PF_CPP,cuda_sources=PF_CUDA[d],functions=['vq8_forward','vq8_resources'],
            extra_cuda_cflags=['-O3',f'-gencode=arch=compute_{arch},code=sm_{arch}',f'-DVQ8_CLK={int(clk)}'])
    return PF_MOD[key]

def pf_forward(qkv,data,d,clocks=None):
    P,S=qkv;cfg=data['config'];B,L=cfg['batch'],cfg['q_len'];dev=P.device
    if P.dtype==torch.bfloat16:raw=P[0] if P.dim()==3 else P;nsplit=ss=0
    else:raw=P;nsplit=S;ss=P.stride(0)
    grid=torch.cuda.get_device_properties(dev).multi_processor_count;segments=B
    nc=(grid+16*L*segments)*64 if clocks is not None else 0
    count=(grid+segments)*128*68+256
    part=torch.empty((count+nc,),device=dev,dtype=torch.float32)
    if nc:part[count:].zero_()
    out=torch.empty((B*L,1024),device=dev,dtype=torch.bfloat16)
    st=6 if torch.cuda.get_device_capability()[0]==9 else 2
    pf_module(d,clocks is not None).vq8_forward(raw.data_ptr(),data['cache_loc'].data_ptr(),data['page_table'].data_ptr(),data['seq_lens'].data_ptr(),
        data['k_cache'].data_ptr(),data['v_cache'].data_ptr(),data['k_scale'].data_ptr(),data['v_scale'].data_ptr(),0,part.data_ptr(),out.data_ptr(),
        B,L,16,2,raw.stride(-2),data['page_table'].shape[1],cfg['page_size'],0,nsplit,8,grid,st,
        cfg['sm_scale']*cfg['qk_scale_factor']*1.4426950408889634,ss,1,torch.cuda.current_stream(dev).cuda_stream)
    if nc:clocks.append(part[count:].view(torch.int64).view(grid+16*L*segments,32))
    return out

def pf_namespace(host,d):
    g=host.__dict__;m=types.ModuleType('pf_layer_'+str(d));v=m.__dict__;v.update(g)
    for k,f in g.items():
        if isinstance(f,types.FunctionType) and f.__globals__ is g:
            h=types.FunctionType(f.__code__,v,f.__name__,f.__defaults__,f.__closure__);h.__kwdefaults__=f.__kwdefaults__;h.__dict__.update(f.__dict__);v[k]=h
    v['_vq8_attention']=lambda qkv,data,setting:pf_forward(qkv,data,d)
    return m

def lab(deadline,weights,state=None):
    global PF_RESULTS
    started=time.monotonic();lines=['META frozen final S11 acda6c62 full verify, FP32 polynomial probability exponent vs native ex2; rescale/max stays native FP32 ex2.',
        'META 8 identical seeds x8 rotating read-cold graph replays; A2 duplicate; original CUPTI critical-path increments. TASK attention gates after real QKV projection.']
    from concurrent.futures import ThreadPoolExecutor
    with ThreadPoolExecutor(max_workers=5) as pool:
        af=pool.submit(tl_activity);fs=[pool.submit(pf_module,d,c) for d in (2,3) for c in ((False,True) if PF_CLOCKS else (False,))]
        host,st=tl_host(weights);act=af.result()
        for f in fs:f.result()
    variants={'A':host,'A2':host,'P2':pf_namespace(host,2),'P3':pf_namespace(host,3)}
    PF_RESULTS=[];device=weights['o'].device
    for B in PF_CASES:
        label='v'+str(B)+'F'
        if time.monotonic()>deadline-8:lines.append('INCOMPLETE '+label);break
        def mk(seed):return host._ap_generate_input(batch=B,ctx=80000,layer='full',q_len=8,spread='agentic',dist='soft',page=1,seed=seed,device=device)
        data=mk(PF_SEEDS[0]);graphs={};out={};profiles={};gates={};cycles={}
        p=st['best7_plans'][(B,8,0)];qkv=host._best7_project(data['attn_input'],'qkv_gate',st,p)
        for d in (2,3):
            got=pf_forward(qkv,data,d);torch.cuda.synchronize();host._attention_store_agrees(qkv,data)
            gate=host._attention_agrees(got,host._attention_reference(qkv,data),host._attention_reference(qkv,data,True))
            assert gate[0],('attention gate',label,d,gate)
            gates[str(d)]=gate
            if PF_CLOCKS:
                rows=[];lab_cold_l2();pf_forward(qkv,data,d,rows);torch.cuda.synchronize()
                cycles[str(d)]=clock_summary(rows[0],torch.cuda.get_device_properties(device).multi_processor_count)
        del qkv,got
        for n,v in variants.items():
            for _ in range(2):v.kernel_fn(data,st)
            torch.cuda.synchronize()
            if n=='A2':graphs[n],out[n],_,_=tl_capture(v,st,data,act,False)
            else:graphs[n],out[n],profiles[n]=cs_profile(v,st,data,act)
        ratios={n:[] for n in variants if n!='A'};times={n:[] for n in variants};drift={n:[] for n in ratios}
        for seed in PF_SEEDS:
            if time.monotonic()>deadline-4:break
            if seed!=PF_SEEDS[0]:cs_copy(data,mk(seed))
            for g in graphs.values():g.replay()
            torch.cuda.synchronize()
            for n in ratios:drift[n].append(cs_delta(out[n],out['A']))
            per={n:[] for n in variants};names=list(variants)
            for i in range(PF_ROUNDS):
                for n in names[i%len(names):]+names[:i%len(names)]:per[n].extend(tl_times(graphs[n],1))
            av={n:statistics.mean(t) for n,t in per.items()}
            for n in variants:times[n].append(av[n])
            for n in ratios:ratios[n].append(av[n]/av['A'])
        row=dict(case=label,A_us=statistics.mean(times['A']),r={n:statistics.mean(r) for n,r in ratios.items()},
            se={n:statistics.stdev(r)/len(r)**.5 if len(r)>1 else 0 for n,r in ratios.items()},inc={n:p['inc']['attn'] for n,p in profiles.items()},
            span={n:p['stages']['attn']['span'] for n,p in profiles.items()},times=times,ratios=ratios,gates=gates,clocks=cycles,
            drift={n:[max(col) for col in zip(*d)] for n,d in drift.items()},seeds=len(times['A']))
        PF_RESULTS.append(row)
        line='PF '+json.dumps(row,separators=(',',':'));lines.append(line);print(line,flush=True)
        del graphs,out,profiles,data;gc.collect();torch.cuda.empty_cache()
    lines.append('END shapes=%d/2 elapsed=%.1fs'%(len(PF_RESULTS),time.monotonic()-started))
    return lines
